local K1 = { 0xC7,0x07,0xD9,0xB7,0xC7,0x5A,0x71,0xA0,0xE7,0x4B,0x93,0x8D,0x4D,0xEA,0xA4,0x4B,0x53,0xBD,0xD8,0xD3,0x1B,0xAA,0xAB,0xE8,0x2F,0xCB,0x9D,0x08,0xA5,0x27,0x23,0xC9 }
