local function xor_str(data, key)
  local n, kl = #data, #key
  local out = table.create and table.create(n) or {}
  for i = 1, n do
    out[i] = char(bit32.bxor(byte(data, i), key[((i - 1) % kl) + 1]))
  end
  return concat(out)
end

local function b64_decode(data)
  if crypt then
    if type(crypt.base64decode) == "function" then
      local ok, r = pcall(crypt.base64decode, data)
      if ok and type(r) == "string" and #r > 0 then return r end
    end
    if type(crypt.base64_decode) == "function" then
      local ok, r = pcall(crypt.base64_decode, data)
      if ok and type(r) == "string" and #r > 0 then return r end
    end
  end
  if type(base64_decode) == "function" then
    local ok, r = pcall(base64_decode, data)
    if ok and type(r) == "string" and #r > 0 then return r end
  end
  local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  local inv = {}
  for i = 1, #b do inv[byte(b, i)] = i - 1 end
  data = data:gsub("%s", ""):gsub("=+$", "")
  local out, n, buf, bits = {}, 0, 0, 0
  for i = 1, #data do
    local v = inv[byte(data, i)]
    if v then
      buf = buf * 64 + v
      bits = bits + 6
      if bits >= 8 then
        bits = bits - 8
        n = n + 1
        out[n] = char(math.floor(buf / (2 ^ bits)) % 256)
        buf = buf % (2 ^ bits)
      end
    end
  end
  return concat(out)
end

